import{_ as a,o as s,c as t,a7 as o}from"./chunks/framework.xMNG87v2.js";const p=JSON.parse('{"title":"VPN connection and gameplay issues","description":"A VPN usually causes connection problems in Minecraft Bedrock. Adjust the MTU size accordingly to address the issue.","frontmatter":{"title":"VPN connection and gameplay issues","outline":"deep","description":"A VPN usually causes connection problems in Minecraft Bedrock. Adjust the MTU size accordingly to address the issue.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/faq/connecting/vpnproblems"}]]},"headers":[],"relativePath":"docs/faq/connecting/vpnproblems.md","filePath":"docs/faq/connecting/vpnproblems.md","lastUpdated":1790689997000}'),n={name:"docs/faq/connecting/vpnproblems.md"};function i(c,e,l,r,m,u){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="vpn-connection-and-gameplay-issues" tabindex="-1">VPN connection and gameplay issues <a class="header-anchor" href="#vpn-connection-and-gameplay-issues" aria-label="Permalink to &quot;VPN connection and gameplay issues&quot;">​</a></h1><p>Minecraft Bedrock commonly has trouble with VPNs for reasons which are not entirely clear.</p><h2 id="make-sure-all-mtu-limits-are-set-correctly" tabindex="-1">Make sure all MTU limits are set correctly <a class="header-anchor" href="#make-sure-all-mtu-limits-are-set-correctly" aria-label="Permalink to &quot;Make sure all MTU limits are set correctly&quot;">​</a></h2><p>A common cause of VPN issues is incorrect, inconsistent or too-large tunnel or link MTUs. You can try testing with smaller MTU sizes and see if the problem goes away.</p><h2 id="reduce-maximum-mtu-in-axolotl-pm-itself" tabindex="-1">Reduce maximum MTU in Axolotl-PM itself <a class="header-anchor" href="#reduce-maximum-mtu-in-axolotl-pm-itself" aria-label="Permalink to &quot;Reduce maximum MTU in Axolotl-PM itself&quot;">​</a></h2><p>If you are not able to alter your VPN MTU sizes, you can try reducing the <code>network.max-mtu-size</code> setting in your <code>pocketmine.yml</code> file. The default setting is 1492 - you may have success with smaller sizes.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>While a smaller MTU may fix your connection issues, it also reduces efficiency, which may cause higher bandwidth consumption and higher data usage.</p></div>',7)])])}const h=a(n,[["render",i]]);export{p as __pageData,h as default};
